// ── base64url en JS pur : ni Buffer, ni btoa/atob (interdits par le bac a sable) ──
const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const enUtf8 = (s) => {
  const o = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c < 0x80) o.push(c);
    else if (c < 0x800) o.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c >= 0xd800 && c < 0xdc00) {
      c = 0x10000 + ((c - 0xd800) << 10) + (s.charCodeAt(++i) - 0xdc00);
      o.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    } else o.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return o;
};
const deUtf8 = (o) => {
  let out = '';
  for (let i = 0; i < o.length; ) {
    const c = o[i++];
    if (c < 0x80) out += String.fromCharCode(c);
    else if (c < 0xe0) out += String.fromCharCode(((c & 31) << 6) | (o[i++] & 63));
    else if (c < 0xf0) out += String.fromCharCode(((c & 15) << 12) | ((o[i++] & 63) << 6) | (o[i++] & 63));
    else {
      const v = (((c & 7) << 18) | ((o[i++] & 63) << 12) | ((o[i++] & 63) << 6) | (o[i++] & 63)) - 0x10000;
      out += String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 1023));
    }
  }
  return out;
};
const b64urlEncode = (texte) => {
  const b = enUtf8(texte);
  let out = '';
  for (let i = 0; i < b.length; i += 3) {
    const n = (b[i] << 16) | ((b[i + 1] || 0) << 8) | (b[i + 2] || 0);
    out += A[(n >> 18) & 63] + A[(n >> 12) & 63];
    if (i + 1 < b.length) out += A[(n >> 6) & 63];
    if (i + 2 < b.length) out += A[n & 63];
  }
  return out;
};
const b64urlDecode = (s) => {
  const o = [];
  for (let i = 0; i < s.length; i += 4) {
    const a = A.indexOf(s[i]), b = A.indexOf(s[i + 1]);
    const c = A.indexOf(s[i + 2]), d = A.indexOf(s[i + 3]);
    if (a < 0 || b < 0) throw new Error('base64url invalide');
    const n = (a << 18) | (b << 12) | ((c < 0 ? 0 : c) << 6) | (d < 0 ? 0 : d);
    o.push((n >> 16) & 255);
    if (c >= 0) o.push((n >> 8) & 255);
    if (d >= 0) o.push(n & 255);
  }
  return deUtf8(o);
};

const body = $input.first().json.body || {};

const tenant_id = body.tenant_id;
const user_id = body.user_id;
const redirect_uri = body.redirect_uri || $env.LICHESS_REDIRECT_URI;

// Validation
const errors = [];
if (!tenant_id) errors.push('tenant_id requis');
if (!user_id) errors.push('user_id requis');
if (!redirect_uri) errors.push('redirect_uri requis (ou configurer LICHESS_REDIRECT_URI)');

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

// Jeton `state` : meme format base64url qu avant, mais sans Buffer (interdit
// par le bac a sable). MCP - Lichess Auth Callback le relit avec le decodeur
// jumeau. Cf. n8n-workflows#476.
const state = b64urlEncode(JSON.stringify({
  tenant_id,
  user_id,
  ts: Date.now(),
  nonce: Math.random().toString(36).substring(2, 15)
}));

// PKCE : le code_verifier est engendre par le noeud Crypto « Generate Verifier »
// (crypto.randomBytes cote n8n), et son challenge par « Hash Challenge ».
// require('crypto') est indisponible ici.

// Lichess OAuth scopes
const scopes = [
  'preference:read',
  'challenge:read',
  'challenge:write', 
  'puzzle:read',
  'team:read',
  'board:play'
].join(' ');

return {
  json: {
    valid: true,
    tenant_id,
    user_id,
    redirect_uri,
    state,
    scopes
  }
};

const input = $('Validate & Prepare').first().json;
const storeResult = $input.first().json;

if (storeResult.statusCode >= 400) {
  return {
    json: {
      success: false,
      error: { code: 500, message: 'Erreur stockage state', details: storeResult }
    }
  };
}

// Build Lichess authorization URL
const clientId = $env.LICHESS_CLIENT_ID;
if (!clientId) {
  return {
    json: {
      success: false,
      error: { code: 500, message: 'LICHESS_CLIENT_ID non configuré' }
    }
  };
}

const params = new URLSearchParams({
  response_type: 'code',
  client_id: clientId,
  redirect_uri: input.redirect_uri,
  scope: input.scopes,
  state: input.state,
  code_challenge: input.code_challenge,
  code_challenge_method: 'S256'
});

const authUrl = `https://lichess.org/oauth?${params.toString()}`;

// Store code_verifier in memory for callback (via state mapping)
// Note: In production, store code_verifier in Redis or similar
// For now, we embed it in state (less secure but functional)

return {
  json: {
    success: true,
    auth_url: authUrl,
    state: input.state,
    code_verifier: input.code_verifier,
    message: 'Redirigez l\'utilisateur vers auth_url pour autorisation Lichess'
  }
};

// PKCE S256 exige du base64url. Le noeud Crypto rend du base64 standard :
// on convertit par simples substitutions de caracteres, sans Buffer.
const j = $input.first().json;
const code_challenge = String(j.code_challenge_b64 || '')
  .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { ...j, code_challenge } }];

